using System;using System.IO;using System.Linq;using System.Text;using System.Collections.Generic;using System.Threading;using System.Threading.Tasks;using System.Security.Cryptography;
namespace FoolLauncher {public static class LoaderTests {
 static void Assert(bool v,string message){if(!v)throw new Exception(message);}static string Hash(byte[] bytes){using(var h=SHA256.Create())return BitConverter.ToString(h.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
 public static void Run(string parent){var service=new PackService(Path.Combine(parent,"loader-tests"));var api=new VanillaService(service);var game=new VanillaVersion{id="1.20.1",type="release"};var vanilla=api.Prepare(game);var forge=api.Prepare(game,new LoaderSelection{Key="forge",Version="47.4.12"});Assert(vanilla.Id!=forge.Id&&forge.DownloadedGame&&service.Index(forge).dependencies["forge"]=="47.4.12","Loader install overwrote vanilla or omitted dependency");Assert(api.Prepare(game,new LoaderSelection{Key="forge",Version="47.4.12"}).Id==forge.Id,"Loader resume did not reuse matching installed profile");var second=api.Prepare(game,new LoaderSelection{Key="forge",Version="47.3.0"});Assert(second.Id!=forge.Id,"Different loader version overwrote profile");var pack=Json.Read<MetaComponents>(Path.Combine(service.Folder(forge),"mmc-pack.json"));Assert(pack.components.Length==2&&pack.components.Any(c=>c.uid=="net.minecraftforge"&&c.version=="47.4.12"),"Prism loader components missing");
  foreach(string key in new[]{"forge","neoforge","fabric-loader","quilt-loader"}){var selection=new LoaderSelection{Key=key,Version="1.0"};selection.Validate();Assert(selection.Uid!=null,"Loader UID missing");}bool rejected=false;try{new LoaderSelection{Key="wrong",Version="1"}.Validate();}catch(InvalidDataException){rejected=true;}Assert(rejected,"Invalid loader key accepted");
  var index=Encoding.UTF8.GetBytes("{\"uid\":\"net.minecraftforge\",\"versions\":[{\"version\":\"47.4.12\",\"recommended\":true,\"requires\":[{\"uid\":\"net.minecraft\",\"equals\":\"1.20.1\"}]},{\"version\":\"52.0.0\",\"requires\":[{\"uid\":\"net.minecraft\",\"equals\":\"1.21.1\"}]}]}");string root="{\"formatVersion\":1,\"packages\":[{\"uid\":\"net.minecraftforge\",\"sha256\":\""+Hash(index)+"\"}]}";var catalog=new LoaderCatalog((url,ct)=>{ct.ThrowIfCancellationRequested();return Task.FromResult(url.EndsWith("/v1/index.json")?Encoding.UTF8.GetBytes(root):index);});var versions=catalog.Versions("forge","1.20.1",CancellationToken.None).GetAwaiter().GetResult();Assert(versions.Length==1&&versions[0].Version=="47.4.12","Loader versions not filtered by selected Minecraft");
  var issue=new JavaRequirementException("Java mismatch",8);Assert(issue is IOException&&issue.Majors.SequenceEqual(new[]{8}),"Typed Java exception lost requested version");Console.WriteLine("PASS: loader profile isolation/resume, four loader component IDs, compatibility filtering and typed Java download requirement.");
 }
}}
